UPDATE tb_evento_corridas SET url_hotsite='https://www.liverun.com.br/etapa/live-run-rio-de-janeiro-ii-2026',url_inscricao='https://www.appliveexperience.com.br/evento/live-run-rio-de-janeiro-ii-2026',categorias='5km, 10km, kids',descricao='LIVE&#x21; RUN XP - RIBEIR&Atilde;O PRETO II 2026 &eacute; mais do que uma corrida, &eacute; um momento de energia e conex&atilde;o&#x21; Voc&ecirc; pode optar por participar das provas de 5 km, 10 km ou da Corrida Kids. Al&eacute;m disso, aproveite a Arena LIVE&#x21;, que oferece m&uacute;sica, atividades de bem-estar e ativa&ccedil;&otilde;es exclusivas. Fa&ccedil;a sua inscri&ccedil;&atilde;o e venha experimentar o ritmo da LIVE&#x21; RUN XP.',descricao_en='LIVE&#x21; RUN XP - RIBEIR&Atilde;O PRETO II 2026 is more than a race, it is a moment of energy and connection&#x21; You can choose to participate in the 5 km, 10 km races or the Kids Race. In addition, enjoy the LIVE&#x21; Arena, which offers music, wellness activities, and exclusive activations. Register and come experience the rhythm of LIVE&#x21; RUN XP.',descricao_es='LIVE&#x21; RUN XP - RIBEIR&Atilde;O PRETO II 2026 es m&aacute;s que una carrera, &iexcl;es un momento de energ&iacute;a y conexi&oacute;n&#x21; Puedes optar por participar en las pruebas de 5 km, 10 km o en la Carrera Kids. Adem&aacute;s, disfruta de la Arena LIVE&#x21;, que ofrece m&uacute;sica, actividades de bienestar y activaciones exclusivas. Haz tu inscripci&oacute;n y ven a experimentar el ritmo de la LIVE&#x21; RUN XP.',descricao_traducoes_meta='{"en": {"description_hash": "051693b43b6e4c1573880029cbaa6813", "source_hash": "8bd025aaa0d92aa88e221d69da8028e1"}, "es": {"description_hash": "4158a469ff0e0d50a30d5ee7d15cc3c2", "source_hash": "8bd025aaa0d92aa88e221d69da8028e1"}}'::jsonb WHERE id_evento=48557;
